  my ($a, $b, $c) = ($1, $2, $3);
  if ($b =~ /\b$attr\s*=\s*"([^"]*)"/) {
    my $cur = $1;
    my $keep = ($mode eq 'num' && $cur =~ /^\d+$/ && $cur >= 1 && $cur <= $lim) || ($mode eq 'from' && $cur eq $lim);
    $b =~ s/\b$attr\s*=\s*"[^"]*"/$attr="$val"/ unless $keep;
  } elsif ($mode ne 'from') { $b .= qq( $attr="$val") }
  "$a$b$c" }gse;
print $t;
TMAEOF
TC_TAG=Server TC_ATTR=port TC_VAL=-1 TC_MODE=set TC_LIM=0 perl "$bk/edit.pl" < "$f" > "$f.tma.new" || exit 1

